python3 -c "
import pyshark

# Lire le PCAP avec les clés SSL
cap = pyshark.FileCapture('capture.pcapng', decryption_key='sslkeylog.txt', display_filter='tcp.port == 443 or tcp.port == 4433')

for i, pkt in enumerate(cap):
    if hasattr(pkt, 'tls') and hasattr(pkt.tls, 'data'):
        print(f'Packet {i}: TLS data: {pkt.tls.data}')
    elif hasattr(pkt, 'tcp') and hasattr(pkt.tcp, 'data'):
        print(f'Packet {i}: TCP data: {pkt.tcp.data}')
    if i > 20:
        break
" 2>&1 | head -50
